#include <iostream>
#include <string>

class Watch {
private:
    int hours_{12};
    int minutes_{0};

public:
    Watch() = default;
    Watch(int h, int m) {
        set_time(h, m);
    }

    void set_time(int h, int m) {
        if (h >= 0 && h < 24 && m >= 0 && m < 60) {
            hours_ = h;
            minutes_ = m;
        }
    }

    void display() const {
        std::cout << "Watch Time: " 
                  << (hours_ < 10 ? "0" : "") << hours_ << ":"
                  << (minutes_ < 10 ? "0" : "") << minutes_ << "\n";
    }
};

class AlarmWatch : public Watch {
private:
    int alarm_hour_{7};
    int alarm_minute_{0};
    bool alarm_enabled_{true};

public:
    AlarmWatch(int h, int m, int ah, int am)
        : Watch(h, m), alarm_hour_{ah}, alarm_minute_{am} {}

    void display_alarm() const {
        display();
        std::cout << "Alarm set for: "
                  << (alarm_hour_ < 10 ? "0" : "") << alarm_hour_ << ":"
                  << (alarm_minute_ < 10 ? "0" : "") << alarm_minute_
                  << (alarm_enabled_ ? " [ACTIVE]" : " [OFF]") << "\n";
    }
};

int main() {
    AlarmWatch my_watch(10, 15, 6, 30);
    my_watch.display_alarm();
    return 0;
}

#include <iostream>
