#include <sstream>
#include <vector>

std::string replace_exact_words(const std::string& text) {
    std::istringstream iss(text);
    std::string word;
    std::string result;
    bool first = true;

    while (iss >> word) {
        // Word-level matching prevents 'woman' from being corrupted by 'man'
        if (word == "man") {
            word = "person";
        } else if (word == "wife") {
            word = "spouse";
        } else if (word == "daughter") {
            word = "child";
        }

        if (!first) {
            result += " ";
        }
        result += word;
        first = false;
    }
    return result;
}

int main() {
    std::string sample = "The man and woman spoke with their daughter";
    std::string converted = replace_exact_words(sample);

    std::cout << "Original : " << sample << "\n";
    std::cout << "Converted: " << converted << "\n";
    return 0;
}

#include <iostream>
#include <stdexcept>

// Demonstrating defensive programming with strict range checks (Medical dosage safeguard)
class RadiationController {
private:
    static constexpr double MAX_SAFE_DOSE_GY = 2.0; // Grays

public:
    void administer_radiation(double dosage_gy) const {
        if (dosage_gy <= 0.0) {
            std::cout << "Error: Dosage must be positive.\n";
            return;
        }

        // Defensive assertion: Circuit-breaker safety interlock
        if (dosage_gy > MAX_SAFE_DOSE_GY) {
            std::cout << "SAFETY INTERLOCK ENGAGED: Excessive radiation requested (" 
                      << dosage_gy << " Gy). Operation aborted.\n";
            return;
        }

        std::cout << "Delivering safe dosage: " << dosage_gy << " Gy successfully.\n";
    }
};

int main() {
    RadiationController machine;
    machine.administer_radiation(1.5); // Safe
    machine.administer_radiation(50.0); // Dangerous over-dose blocked
    return 0;
}
